// notification.js
// Utilities for browser push notification registration and permission

import { savePushNotificationDetails } from './api';

// Helper to convert VAPID key
export function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

// Main function to request permission and register push
export async function registerForPushNotifications(token, publicVapidKey) {
    console.log('Registering for push notifications with token:', token);
  // 1. Check if already granted
  if (Notification.permission === 'granted') {
    console.log('Notification permission already granted');
    // Optionally, check if already subscribed
    const registration = await navigator.serviceWorker.ready;
    const existing = await registration.pushManager.getSubscription();
    if (existing) {
      // Already subscribed, send to backend if needed
      await savePushNotificationDetails(token, existing);
      return existing;
    }
  }

  // 2. Ask for permission if not granted
  console.log('Requesting notification permission');
  const permission = await Notification.requestPermission();
  if (permission !== 'granted') {
    throw new Error('Notification permission denied');
  }

  // 3. Register service worker and subscribe
  const registration = await navigator.serviceWorker.ready;
  const subscription = await registration.pushManager.subscribe({
    userVisibleOnly: true,
    applicationServerKey: urlBase64ToUint8Array(publicVapidKey),
  });
  // 4. Send subscription to backend
  await savePushNotificationDetails(token, subscription);
  return subscription;
}
