import React, { useState, useEffect } from 'react';
import { ListGroup, Card, Row, Col } from 'react-bootstrap';
import { fetchSignals } from '../api';
import CryptoLogo from './CryptoLogo';
import { useNavigate } from 'react-router-dom';
import {getUserData} from '../jerryTokenUtil';
import SignalPill from './SignalPill';
import { isDarkModeEnabled } from '../settings';
import './SignalData.css';

const SignalData = ({ onDataLoaded, polyglot, refreshSignal, triggerRefresh, filters }) => {
    const [allSignals, setAllSignals] = useState([]);
    const [filteredSignals, setFilteredSignals] = useState([]);
    const [dataLoadedTs, setDataLoadedTs] = useState(null);
    const [loading, setLoading] = useState(true);
    const [refreshing, setRefreshing] = useState(false);
    const [error, setError] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [selectedSignal, setSelectedSignal] = useState(null);
    const navigate = useNavigate();
    const userData = getUserData();

    const signalDataKey = `${userData.hashedEmail}.signalData`;
    const signalDataUpdatedAtKey = `${userData.hashedEmail}.signalDataUpdatedAt`;

    const darkMode = isDarkModeEnabled();
    const darkBg = '#101624'; // blueish, near-black
    const darkCard = '#18213a';
    const darkBorder = 'rgba(44, 62, 80, 0.6)';
    const darkText = '#e0e6f0';

    const loadSignals = async (isRefresh = false) => {
        try {
            if (isRefresh) {
                setRefreshing(true);
            } else {
                setLoading(true);
            }

            // Check session storage for existing data
            const storedData = sessionStorage.getItem(signalDataKey);
            const signalDataUpdatedAt = sessionStorage.getItem(signalDataUpdatedAtKey);

            let signals;
            if (storedData && signalDataUpdatedAt && !isRefresh) {
                signals = JSON.parse(storedData);
                setDataLoadedTs(signalDataUpdatedAt);
                onDataLoaded(signalDataUpdatedAt);
            } else {
                // Fetch data from API
                const jerryToken = localStorage.getItem('jerryToken');
                signals = await fetchSignals(jerryToken);
                const timestamp = new Date().toLocaleString();
                setDataLoadedTs(timestamp);
                sessionStorage.setItem(signalDataKey, JSON.stringify(signals));
                sessionStorage.setItem(signalDataUpdatedAtKey, timestamp);
                if (onDataLoaded) {
                    onDataLoaded(timestamp);
                }
            }

            // Sort the signals
            const sortedSignals = signals.sort((a, b) => {
                const order = { buy: 1, sell: 2, hold: 3 };
                const signalComparison = order[a.signal] - order[b.signal];
                if (signalComparison === 0) {
                    return a.symbol.localeCompare(b.symbol);
                }
                return signalComparison;
            });
            setAllSignals(sortedSignals);
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
            setRefreshing(false);
        }
    };

    const handleCardClick = (signal) => {
        setSelectedSignal(signal);
        navigate('/details', { state: { signal, lastUpdatedAt: dataLoadedTs } });
    };

    const handleAddClick = () => {
        navigate('/add-crypto')
    };

    useEffect(() => {
        loadSignals();
    }, []); // Initial load on mount

    // Apply filters whenever allSignals or filters change
    useEffect(() => {
        if (!allSignals || allSignals.length === 0) {
            setFilteredSignals([]);
            return;
        }
        // If no filters selected, show all
        if (!filters || (!filters.market && !filters.signal && !filters.reason)) {
            setFilteredSignals(allSignals);
            return;
        }
        // Apply filters
        setFilteredSignals(
            allSignals.filter(s => {
                if (filters.market && s.market !== filters.market) return false;
                if (filters.signal && s.signal !== filters.signal) return false;
                if (filters.reason && s.signalReason !== filters.reason) return false;
                return true;
            })
        );
    }, [allSignals, filters]);

    useEffect(() => {
        if (refreshSignal) {
            loadSignals(true);
        }
    }, [refreshSignal]);

    return (
        <section className={darkMode ? 'signal-section-dark' : 'signal-section'}>
            {/* Main Content */}
            <Row xs={1} sm={2} md={3} lg={4} className="g-4">
            {/* "+ Add" Card */}
    
                {/* Desktop Version */}
                <Col className="d-none d-md-block">
                    <div className="signal-add-container" style={{ gap: '8px', display: 'flex', flexDirection: 'column', height: '100%', justifyContent: 'center', alignItems: 'stretch' }}>
                        <Card
                            className={`shadow-sm mb-2 signal-card${darkMode ? ' signal-card-dark' : ''}`}
                            onClick={() => triggerRefresh()}
                            style={{
                                minHeight: '80px',
                                height: '80px',
                                maxHeight: '90px',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                marginBottom: '8px',
                                cursor: 'pointer',
                                border: darkMode ? undefined : '2px solid rgba(108, 117, 125, 0.07)',
                                background: darkMode ? undefined : '#f8fafc',
                                boxShadow: darkMode ? undefined : '0 2px 8px 0 rgba(0,0,0,0.03)',
                                transition: 'box-shadow 0.2s, border 0.2s',
                            }}
                        >
                            <Card.Body className="d-flex justify-content-center align-items-center" style={{ minHeight: '50px', padding: 0 }}>
                                <h4 className={`m-0 signal-add-icon${darkMode ? ' signal-add-icon-dark' : ''}`} style={{ color: darkMode ? '#e0e6f0' : '#495057', fontSize: '1.7rem', lineHeight: 1 }}>
                                    ↻
                                </h4>
                            </Card.Body>
                        </Card>
                        <Card
                            className={`shadow-sm signal-card${darkMode ? ' signal-card-dark' : ''}`}
                            onClick={() => handleAddClick()}
                            style={{
                                minHeight: '80px',
                                height: '80px',
                                maxHeight: '90px',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                marginBottom: 0,
                                cursor: 'pointer',
                                border: darkMode ? undefined : '2px solid rgba(108, 117, 125, 0.07)',
                                background: darkMode ? undefined : '#f8fafc',
                                boxShadow: darkMode ? undefined : '0 2px 8px 0 rgba(0,0,0,0.03)',
                                transition: 'box-shadow 0.2s, border 0.2s',
                            }}
                        >
                            <Card.Body className="d-flex justify-content-center align-items-center" style={{ minHeight: '50px', padding: 0 }}>
                                <h4 className={`m-0 signal-add-icon${darkMode ? ' signal-add-icon-dark' : ''}`} style={{ color: darkMode ? '#e0e6f0' : '#495057', fontSize: '1.7rem', lineHeight: 1 }}>
                                    ＋
                                </h4>
                            </Card.Body>
                        </Card>
                    </div>
                </Col>

                {/* Mobile Version */}
                <Row className="g-2 d-flex d-md-none justify-content-center" style={{ width: '100%', margin: 0, marginTop: 16 }}>
                    <Col xs={6} className="px-1" style={{ maxWidth: '48%', flex: '0 0 48%' }}>
                        <Card
                            className={`shadow-sm signal-card signal-card-mobile${darkMode ? ' signal-card-dark' : ''}`}
                            onClick={() => triggerRefresh()}
                            style={{
                                minHeight: '80px',
                                height: '80px',
                                maxHeight: '90px',
                                width: '100%',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                cursor: 'pointer',
                                border: darkMode ? undefined : '2px solid rgba(108, 117, 125, 0.07)',
                                background: darkMode ? undefined : '#f8fafc',
                                boxShadow: darkMode ? undefined : '0 2px 8px 0 rgba(0,0,0,0.03)',
                                transition: 'box-shadow 0.2s, border 0.2s',
                            }}
                        >
                            <Card.Body className="d-flex justify-content-center align-items-center p-2" style={{ minHeight: '50px', padding: 0 }}>
                                <Card.Title
                                    className={`signal-mobile-icon${darkMode ? ' signal-mobile-icon-dark' : ''}`}
                                    style={{ color: darkMode ? '#e0e6f0' : '#495057', fontSize: '1.7rem', lineHeight: 1 }}
                                >
                                    ↻
                                </Card.Title>
                            </Card.Body>
                        </Card>
                    </Col>
                    <Col xs={6} className="px-1" style={{ maxWidth: '48%', flex: '0 0 48%' }}>
                        <Card
                            className={`shadow-sm signal-card signal-card-mobile${darkMode ? ' signal-card-dark' : ''}`}
                            onClick={() => handleAddClick()}
                            style={{
                                minHeight: '80px',
                                height: '80px',
                                maxHeight: '90px',
                                width: '100%',
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                cursor: 'pointer',
                                border: darkMode ? undefined : '2px solid rgba(108, 117, 125, 0.07)',
                                background: darkMode ? undefined : '#f8fafc',
                                boxShadow: darkMode ? undefined : '0 2px 8px 0 rgba(0,0,0,0.03)',
                                transition: 'box-shadow 0.2s, border 0.2s',
                            }}
                        >
                            <Card.Body className="d-flex justify-content-center align-items-center p-2" style={{ minHeight: '50px', padding: 0 }}>
                                <Card.Title
                                    className={`signal-mobile-icon${darkMode ? ' signal-mobile-icon-dark' : ''}`}
                                    style={{ color: darkMode ? '#e0e6f0' : '#495057', fontSize: '1.7rem', lineHeight: 1 }}
                                >
                                    +
                                </Card.Title>
                            </Card.Body>
                        </Card>
                    </Col>
                </Row>

            {/* Existing Signals */}
            {filteredSignals && filteredSignals.map((signal, index) => (
                    <Col key={index}>
                        <Card
                            className={`h-100 shadow-sm signal-card${darkMode ? ' signal-card-dark' : ''} signal-card-signal signal-card-signal-${signal.signal}`}
                            onClick={() => handleCardClick(signal)}
                        >
                            <Card.Body className={`p-1${darkMode ? ' signal-card-text-dark' : ' signal-card-text'}`}>
                                <Card.Title
                                    className={`signal-title${darkMode ? ' signal-title-dark' : ''}`}
                                >
                                    {/* Timeframe Badge */}
                                    <span
                                        className={`badge mb-0 signal-badge-timeframe${darkMode ? ' signal-badge-timeframe-dark' : ''}`}
                                        style={{
                                            display: 'inline-flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            borderRadius: '50%',
                                            width: '1.6em',
                                            height: '1.6em',
                                            minWidth: '1.6em',
                                            minHeight: '1.6em',
                                            fontSize: '0.6em', // smaller text
                                            fontWeight: 600,
                                            marginRight: '0.5em',
                                            background: darkMode ? '#22304a' : 'rgba(110,110,110,1)',
                                            color: darkMode ? '#e0e6f0' : '#fff',
                                            padding: 0,
                                        }}
                                    >
                                        {signal.timeframe}
                                    </span>

                                    {/* Symbol Badge */}
                                    <span
                                        className={`badge mb-0 signal-badge-symbol${darkMode ? ' signal-badge-symbol-dark' : ''}`}
                                        style={{
                                            background: 'transparent',
                                            color: darkMode ? '#e0e6f0' : '#222',
                                            fontSize: '1rem',
                                            fontWeight: 500,
                                            padding: 0,
                                        }}
                                    >
                                        [{signal.symbol.replace('USDC', '').replace('USDT', '')}] {polyglot.t(`cryptoPairs.${signal.symbol}`)}
                                    </span>
                                </Card.Title>

                                <div className="d-flex align-items-center">
                                    <Col xs={4} className="text-center">
                                        <CryptoLogo
                                            cryptoPairName={signal.symbol}
                                            customStyle={{
                                                width: '70%',
                                            }}
                                        />
                                    </Col>
                                    <Col xs={8} className="ms-3">
                                        <Card.Text className={darkMode ? 'signal-card-text-dark' : 'signal-card-text'}>
                                            <div className={darkMode ? 'signal-market-label-dark' : 'signal-market-label'}>
                                                {polyglot.t(`markets.${signal.market}`)}
                                            </div>
                                            ${signal.price}
                                            <br />
                                            <div className="signal-pill-container">
                                                <SignalPill polyglot={polyglot} signal={signal} />
                                            </div>
                                        </Card.Text>
                                    </Col>
                                </div>
                            </Card.Body>
                        </Card>
                    </Col>
                ))}
            </Row>

            {!loading && (!filteredSignals || filteredSignals.length === 0) && (
                <ListGroup.Item className={`signal-no-signals${darkMode ? ' signal-no-signals-dark' : ''}`}>
                    {polyglot.t('signal.noSignals')}
                </ListGroup.Item>
            )}
        </section>
    );
};

export default SignalData;
