import AppRoutes from "./AppRoutes";
import PolyglotProvider from "./components/PolyglotProvider";
import { NotificationProvider } from "./contexts/NotificationContext";
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { isDarkModeEnabled } from './settings';
import React, { useMemo } from 'react';

const App = () => {
  const darkMode = isDarkModeEnabled();
  const toastTheme = useMemo(() => (darkMode ? 'dark' : 'light'), [darkMode]);
  return (
    <PolyglotProvider>
      <NotificationProvider>
        <>
          <AppRoutes />
          <ToastContainer position="top-center" autoClose={3500} theme={toastTheme} />
        </>
      </NotificationProvider>
    </PolyglotProvider>
  );
}

export default App;