import { useContext, useEffect, useRef } from "react";
import { toast, ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { NotificationContext } from "../contexts/NotificationContext";
import { isDarkModeEnabled } from "../settings";

// ...existing code...

const NotificationModal = ({ polyglot }) => {
  const { notification, closeNotification } = useContext(NotificationContext);
  const darkMode = isDarkModeEnabled();
  const toastIdRef = useRef();

  useEffect(() => {
    if (notification) {
      // Market name with capital letter
      const marketRaw = notification.market_name || "spot";
      const market = marketRaw.charAt(0).toUpperCase() + marketRaw.slice(1).toLowerCase();
      // Signal (Buy/Sell)
      const signal = notification.last_signal ? notification.last_signal.charAt(0).toUpperCase() + notification.last_signal.slice(1).toLowerCase() : "";
      // Crypto pair and timeframe
      const pair = notification.symbol || "";
      const timeframe = notification.timeframe || "";
      // Reason and icon
      const reason = notification.signal_reason || "trend";
      let reasonIcon = "";
      if (reason === "trend") reasonIcon = "📊";
      else if (reason === "reversal") reasonIcon = "🔄";
      else if (reason === "spike") {
        reasonIcon = (signal.toLowerCase() === "buy") ? "🚀" : "💣";
      }
      // Toast message
      const msg = `[${market}] ${signal} ${pair}/${timeframe} ${reasonIcon}`;
      // Prevent duplicate toasts
      const toastKey = notification.id || `${pair}-${timeframe}-${signal}-${reason}`;
      if (!toast.isActive(toastIdRef.current)) {
        toastIdRef.current = toast.warn(msg, {
          toastId: toastKey,
          position: "top-center",
          autoClose: 1200,
          closeOnClick: true,
          draggable: false,
          pauseOnHover: true,
          theme: darkMode ? "dark" : "light",
          onClose: closeNotification,
        });
      }
    }
    // Only run when notification changes
    // eslint-disable-next-line
  }, [notification, darkMode]);

  return <ToastContainer position="top-center" newestOnTop={false} closeOnClick={true} />;
};


export default NotificationModal;
