import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { useEffect, useState, useContext } from 'react';
import Login from './pages/Login';
import MainPage from './pages/MainPage';
import Header from './pages/Header';
import Footer from './pages/Footer';
import { PolyglotContext } from './components/PolyglotProvider';
import CryptoDetails from './pages/CryptoDetails';
import SmallHeader from './pages/SmallHeader';
import NotificationModal from './components/NotificationModal';
import Profile from './pages/Profile';
import AddCryptoPage from './pages/AddCrypto';
import { isDarkModeEnabled } from './settings';
import PayWall from './pages/PayWall';
import Upgrade from './pages/Upgrade';
import Payment from './pages/Payment';
import NotificationConfig from './pages/NotificationConfig';
import Settings from './pages/Settings';

const AppRoutes = () => {
    const { polyglot } = useContext(PolyglotContext);
    // Use polling to force rerender on dark mode toggle
    const [mode, setMode] = useState(isDarkModeEnabled());
    useEffect(() => {
        const interval = setInterval(() => {
            setMode(isDarkModeEnabled());
        }, 300);
        return () => clearInterval(interval);
    }, []);
    const darkMode = mode;

    const HeaderWrapper = () => {
        const location = useLocation();
        if (location.pathname === '/') {
            return <Header />;
        }
        return <SmallHeader polyglot={polyglot} />;
    };

    return (
        <Router>
            <div
                className={`app${darkMode ? ' app-dark' : ''}`}
                style={{
                    display: 'flex',
                    flexDirection: 'column',
                    minHeight: '100vh',
                    overflow: 'hidden',
                    background: darkMode ? '#101624' : '#fff',
                    color: darkMode ? '#e0e6f0' : '#222',
                }}
            >
                {/* Conditional Header */}
                <HeaderWrapper />

                <NotificationModal polyglot={polyglot} />

                {/* Main Content */}
                <main
                    className="content"
                    style={{
                        flex: 1,
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        justifyContent: 'flex-start',
                        overflow: 'auto',
                        paddingBottom: '25px',
                        background: darkMode ? '#101624' : '#fff',
                        color: darkMode ? '#e0e6f0' : '#222',
                    }}
                >
                    <Routes>
                        <Route path="/" element={<Login polyglot={polyglot} />} />
                        <Route path="/main" element={<MainPage polyglot={polyglot} />} />
                        <Route path="/add-crypto" element={<AddCryptoPage polyglot={polyglot} />} />
                        <Route path="/details" element={<CryptoDetails polyglot={polyglot} />} />
                        <Route path="/profile" element={<Profile polyglot={polyglot} />} />
                        <Route path="/paywall" element={<PayWall polyglot={polyglot} />} />
                        <Route path="/upgrade" element={<Upgrade polyglot={polyglot} />} />
                        <Route path="/payment" element={<Payment />} />
                        <Route path="/notification-config" element={<NotificationConfig polyglot={polyglot} />} />
                        <Route path="/settings" element={<Settings polyglot={polyglot} />} />
                    </Routes>
                </main>

                {/* Footer */}
                <Footer />
            </div>
        </Router>
    );
};

export default AppRoutes;