import React, { useState, useEffect } from 'react';
import { Modal, Form, Button, Spinner } from 'react-bootstrap';
import { fetchTimeframes, fetchMarkets, addCryptoMarket } from '../api';
import { getUserData } from '../jerryTokenUtil';
import CryptoLogo from './CryptoLogo';
import { isDarkModeEnabled } from '../settings';
import { useNavigate } from 'react-router-dom';
import { getProfile as getProfileCache, getPlans, checkPlanLimit } from '../sessionCache';
import { basepath } from '../pages/Header';

const CryptoConfigModal = ({ show, onClose, crypto, polyglot, onSubmit }) => {
  const [timeframes, setTimeframes] = useState([]);
  const [markets, setMarkets] = useState([]);
  const [selectedTimeframe, setSelectedTimeframe] = useState('');
  const [selectedMarket, setSelectedMarket] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [userProfile, setUserProfile] = useState(null);
  const [plans, setPlans] = useState(null);
  const userData = getUserData();
  const navigate = useNavigate();

  const timeframesKey = `${userData.hashedEmail}.timeframes`;
  const marketsKey = `${userData.hashedEmail}.markets`;

  useEffect(() => {
    if (show) {
      fetchData();
    }
  }, [show]);

  const fetchData = async () => {
    setLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem('jerryToken');
      const storedTimeframes = sessionStorage.getItem(timeframesKey);
      const storedMarkets = sessionStorage.getItem(marketsKey);

      let timeframesData = [];
      let marketsData = [];

      if (storedTimeframes && storedMarkets) {
        timeframesData = JSON.parse(storedTimeframes);
        marketsData = JSON.parse(storedMarkets);
      } else {
        [timeframesData, marketsData] = await Promise.all([
          fetchTimeframes(token),
          fetchMarkets(token),
        ]);

        sessionStorage.setItem(timeframesKey, JSON.stringify(timeframesData));
        sessionStorage.setItem(marketsKey, JSON.stringify(marketsData));
      }

      // Load user profile and plans for filtering
      const [profile, plansData] = await Promise.all([
        getProfileCache(token),
        getPlans(basepath)
      ]);
      setUserProfile(profile);
      setPlans(plansData);

      // Filter timeframes based on user's plan
      const allowedTimeframes = plansData[profile.plan_name.toLowerCase()]?.timeframes || [];
      const filteredTimeframes = timeframesData.filter(tf => allowedTimeframes.includes(tf));

      setTimeframes(filteredTimeframes || []);
      setMarkets(marketsData || []);

      setSelectedTimeframe(filteredTimeframes?.[0] || '');
      setSelectedMarket(marketsData?.[0] || '');
    } catch (err) {
      setError(polyglot.t('modal.fetchError'));
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = async () => {
    const payload = {
      pair_name: crypto.pair_name,
      market_name: selectedMarket,
      timeframe: selectedTimeframe,
    };

    // Check if the selected timeframe is allowed for the user's plan
    if (userProfile && plans) {
      const isTimeframeAllowed = checkPlanLimit(userProfile, plans, 'timeframes', selectedTimeframe);
      if (!isTimeframeAllowed) {
        setError(polyglot.t('error.plan_limit_reached'));
        return;
      }
    }

    try {
      const token = localStorage.getItem('jerryToken');
      await addCryptoMarket(token, payload);

      onSubmit(payload);
      onClose();
    } catch (err) {
      navigate('/paywall');
    }
  };

  const darkMode = isDarkModeEnabled();
  const darkBg = '#101624'; // blueish, near-black
  const darkCard = '#18213a';
  const darkBorder = 'rgba(44, 62, 80, 0.6)';
  const darkText = '#e0e6f0';

  return (
    <Modal show={show} onHide={onClose} centered
      style={darkMode ? {
        background: 'rgba(16,22,36,0.7)', // semi-transparent overlay for dark mode
      } : {
        background: 'rgba(224,215,212,0.7)', // default light overlay
      }}
      dialogClassName={darkMode ? 'crypto-config-modal-dark' : ''}
    >
      <Modal.Header closeButton style={darkMode ? { background: darkCard, color: darkText, borderBottom: `1px solid ${darkBorder}` } : {}}>
        <Modal.Title>
          <div style={{ fontSize: '1.2rem', fontWeight: 600, color: darkMode ? darkText : '#6c757d' }}>
            [{crypto.base_currency}] {polyglot.t(`cryptos.${crypto.base_currency}`)}
          </div>
        </Modal.Title>
      </Modal.Header>
      <Modal.Body style={darkMode ? { background: darkBg, color: darkText } : {}}>
        {loading ? (
          <div className="text-center" style={darkMode ? { color: darkText } : {}}>
            <Spinner animation="border" role="status" />
            <p>{polyglot.t('modal.loadingData')}</p>
          </div>
        ) : error ? (
          <div className="text-danger text-center">
            <p>{error}</p>
          </div>
        ) : (
          <Form style={darkMode ? { color: darkText } : {}}>
            {/* Market Selection */}
            <Form.Group controlId="marketSelect">
              <div className="d-flex flex-column align-items-center mb-2">
                <CryptoLogo
                  cryptoPairName={crypto.pair_name}
                  customStyle={{ width: '100px', height: '100px' }}
                />
              </div>
              <Form.Label style={darkMode ? { color: darkText } : {}}>{polyglot.t('label.market')}</Form.Label>
              <div className="d-flex flex-wrap gap-2">
                {markets.map((market) => (
                  <Button
                    key={market}
                    variant={selectedMarket === market ? 'primary' : 'outline-secondary'}
                    onClick={() => setSelectedMarket(market)}
                    className="d-flex align-items-center"
                    style={darkMode ? {
                      background: selectedMarket === market ? '#4fc3f7' : darkCard,
                      color: selectedMarket === market ? '#18213a' : darkText,
                      border: `1px solid ${darkBorder}`,
                    } : {}}
                  >
                    {polyglot.t(`markets.${market}`)}
                  </Button>
                ))}
              </div>
            </Form.Group>
            {/* Timeframe Selection */}
            <Form.Group controlId="timeframeSelect" className="mt-3">
              <Form.Label style={darkMode ? { color: darkText } : {}}>{polyglot.t('label.timeframe')}</Form.Label>
              <div className="d-flex flex-wrap gap-2">
                {timeframes.map((timeframe) => (
                  <Button
                    key={timeframe}
                    variant={selectedTimeframe === timeframe ? 'primary' : 'outline-secondary'}
                    onClick={() => setSelectedTimeframe(timeframe)}
                    style={darkMode ? {
                      background: selectedTimeframe === timeframe ? '#4fc3f7' : darkCard,
                      color: selectedTimeframe === timeframe ? '#18213a' : darkText,
                      border: `1px solid ${darkBorder}`,
                    } : {}}
                  >
                    {polyglot.t(`timeframes.${timeframe}`)}
                  </Button>
                ))}
              </div>
            </Form.Group>
          </Form>
        )}
      </Modal.Body>
      <Modal.Footer style={darkMode ? { background: darkCard, color: darkText, borderTop: `1px solid ${darkBorder}` } : {}}>
        {error ? (
          <Button
            variant="secondary"
            onClick={onClose}
            style={darkMode ? { background: '#22304a', color: darkText, border: 'none' } : {}}
          >
            {polyglot.t('notification.close')}
          </Button>
        ) : (
          <>
            <Button variant="secondary" onClick={onClose} style={darkMode ? { background: '#22304a', color: darkText, border: 'none' } : {}}>
              {polyglot.t('label.cancel')}
            </Button>
            <Button
              variant="primary"
              onClick={handleConfirm}
              disabled={loading || error || !selectedTimeframe || !selectedMarket}
              style={darkMode ? { background: '#4fc3f7', color: '#18213a', border: 'none' } : {}}
            >
              {polyglot.t('label.confirm')}
            </Button>
          </>
        )}
      </Modal.Footer>
    </Modal>
  );
};

export default CryptoConfigModal;
