import { Button, Card, Container } from "react-bootstrap";
import { useLocation, useNavigate } from "react-router-dom";
import ConfirmRemoveModal from "../components/ConfirmRemovalModal";
import useSessionExpired from "../hooks/useSessionExpired";
import { useEffect, useState } from "react";
import CryptoLogo from "../components/CryptoLogo";
import { getSignalStyles } from "../signalUtil";
import BackButton from "../components/BackButton";
import { FaBell, FaBellSlash, FaCopy, FaCheck, FaSync } from "react-icons/fa";
import { removeCryptoMarket, checkCryptoNotificationStatus, getOHLCData } from "../api";
import CandlestickChart from "../components/CandlestickChart";
import { isDarkModeEnabled } from "../settings";
import SignalPill from "../components/SignalPill";
import { getSignalsByDetails } from "../api";

const AUTO_REFRESH_INTERVAL_SEC = 60; // Change this value for testing

const CryptoDetails = ({ polyglot, lastUpdatedAt: propLastUpdatedAt }) => {
    const location = useLocation();

    const defaultSignal = {
        symbol: "",
        market: "",
        timeframe: "",
        price: 0,
        takeProfit: 0,
        stopLoss: 0,
        signal: "",
        signalReason: "none"
    };

    const initialSignal = location.state?.signal || defaultSignal;
    const [signal, setSignal] = useState(initialSignal);

    
    const [showModal, setShowModal] = useState(false);
    const [notificationsEnabled, setNotificationsEnabled] = useState(false);
    const [copiedPrice, setCopiedPrice] = useState(null);
    const SessionExpiredModal = useSessionExpired(polyglot);
    const navigate = useNavigate();
    const token = localStorage.getItem("jerryToken");
    const marketName = signal ? polyglot.t(`markets.${signal.market}`) : '';
    const { badgeStyles, href } = signal ? getSignalStyles(signal) : {};

    // Parse query params for deeplink support
    const searchParams = new URLSearchParams(location.search);
    const deeplinkCryptopair = searchParams.get('cryptopair');
    const deeplinkMarket = searchParams.get('market');
    const deeplinkTimeframe = searchParams.get('timeframe');

    const roiPercentage = signal ? ((signal.takeProfit - signal.price) / signal.price) * 100 : 0;
    const investmentAmounts = [500, 1000, 1500, 2500, 7000];

    const [selectedLeverage, setSelectedLeverage] = useState(1);
    const leverageOptions = [1, 2, 5, 25, 125];

    const [ohlcData, setOhlcData] = useState([]);
    const [isChartLoading, setIsChartLoading] = useState(true);

    // Add a loading state for refresh
    const [refreshing, setRefreshing] = useState(false);

    const initialLastUpdated = propLastUpdatedAt || location.state?.lastUpdatedAt || '—';
    const [lastUpdatedAt, setLastUpdatedAt] = useState(initialLastUpdated);

    // Update signal and lastUpdatedAt when location.state changes (for notification navigation)
    useEffect(() => {
        if (location.state?.signal) {
            setSignal(location.state.signal);
        }
        if (location.state?.lastUpdatedAt) {
            setLastUpdatedAt(location.state.lastUpdatedAt);
        }
    }, [location.state]);

    // Load OHLC data
    useEffect(() => {
        const loadOHLCData = async () => {
            try {
                setIsChartLoading(true);
                const data = await getOHLCData(token, signal.symbol, signal.market, signal.timeframe);
                setOhlcData(data);
            } catch (err) {
                console.error("Failed to fetch OHLC data", err);
            } finally {
                setIsChartLoading(false);
            }
        };

        loadOHLCData();
    }, [signal, token]);

    // Fetch notification status
    useEffect(() => {
        const fetchNotificationStatus = async () => {
            try {
                const response = await checkCryptoNotificationStatus(token, signal.symbol, signal.market, signal.timeframe);
                setNotificationsEnabled(response.enabled);
            } catch (error) {
                console.error("Failed to fetch notification status:", error);
            }
        };
        fetchNotificationStatus();
    }, [signal, token]);

    // Handle notification bell click: redirect to NotificationConfig
    const handleNotificationToggle = () => {
        navigate('/notification-config', {
            state: {
                crypto: signal.symbol,
                timeframe: signal.timeframe,
                market: signal.market,
            },
        });
    };

    // Copy value to clipboard
    const copyToClipboard = (value) => {
        navigator.clipboard.writeText(value).then(() => {
            setCopiedPrice(value);
            setTimeout(() => setCopiedPrice(null), 2000);
        });
    };

    // Remove crypto market
    const onConfirmRemove = async () => {
        await removeCryptoMarket(token, {
            pair_name: signal.symbol,
            market_name: signal.market,
            timeframe: signal.timeframe,
        });

        navigate("/main", {
            state: {
                alert: polyglot.t("cryptoDetails.unfollowed", {
                    crypto: signal.symbol,
                    timeframe: signal.timeframe,
                    market: marketName,
                }),
            },
        });
    };

    const darkMode = isDarkModeEnabled();
    const darkBg = '#101624'; // blueish, near-black
    const darkCard = '#18213a';
    const darkBorder = 'rgba(44, 62, 80, 0.6)';
    const darkText = '#e0e6f0';

    // Add refresh handler
    const handleRefresh = async () => {
        setRefreshing(true);
        try {
            const symbol = signal?.symbol || deeplinkCryptopair;
            const market = signal?.market || deeplinkMarket;
            const timeframe = signal?.timeframe || deeplinkTimeframe;

            if (!symbol || !market || !timeframe) {
                console.warn("Missing params for refresh");
                return;
            }

            const updatedSignal = await getSignalsByDetails(token, symbol, market, timeframe);
            if (updatedSignal) {
                setSignal(updatedSignal);
                setLastUpdatedAt(new Date().toLocaleString());
            }
        } catch (err) {
            if (signal.symbol === "") {
                    console.error("Failed to refresh signal details", err);
                    navigate('/main', {state: { 
                    alert: polyglot.t('label.cryptoDetailsError') 
                }})
            }
        } finally {
            setRefreshing(false);
        }
    };

    useEffect(() => {
        if (deeplinkCryptopair && deeplinkMarket && deeplinkTimeframe) {
            handleRefresh();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);



    // Scroll to top on mount
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'auto' });
    }, []);

    // Auto-refresh every N seconds
    useEffect(() => {
        const interval = setInterval(() => {
            handleRefresh();
        }, AUTO_REFRESH_INTERVAL_SEC * 1000);
        return () => clearInterval(interval);
    }, []);

    return (
        <Container
            className={`mt-4${darkMode ? ' crypto-details-dark' : ''}`}
            style={darkMode ? {
                background: darkBg,
                color: darkText,
                borderRadius: '12px',
                boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)'
            } : { height: '100%' }}
        >
            <BackButton polyglot={polyglot} />
            <Card
                className={`mt-3${darkMode ? ' crypto-details-card-dark' : ''}`}
                style={darkMode ? {
                    background: darkCard,
                    color: darkText,
                    border: `1px solid ${darkBorder}`,
                } : {}}
            >
                <Card.Header style={darkMode ? { background: '#22304a', color: darkText } : {}}>
                    <div className="d-flex align-items-center justify-content-between">
                        <div className="d-flex align-items-center">
                            <CryptoLogo cryptoPairName={signal.symbol} />
                            <div className="ms-3">
                                <h5 className="mb-0" style={{ marginBottom: 8 }}>{polyglot.t(`cryptoPairs.${signal.symbol}`)}</h5>
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '1rem', marginBottom: 6, marginTop: 10    }}>
                                    <span className={`signal-pill signal-pill-hold${darkMode ? ' signal-pill-dark' : ''}`} style={{ fontSize: '0.95rem', padding: '2px 12px', borderRadius: '16px', letterSpacing: 1, marginRight: 6, fontWeight: 600 }}>
                                        {signal.timeframe}
                                    </span>
                                    <span style={{ fontSize: '0.95rem', color: darkMode ? '#8fa3c8' : '#6c757d', fontWeight: 500 }}>{marketName}</span>
                                </div>
                                <div style={{ fontSize: '0.85rem', color: darkMode ? '#8fa3c8' : '#6c757d', fontWeight: 400, marginTop: 10, minWidth: 260, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', display: 'flex', alignItems: 'center', gap: 6 }}>
                                    {refreshing ? (
                                        <span>{polyglot.t('label.loading')}</span>
                                    ) : (
                                        <span>{lastUpdatedAt}</span>
                                    )}
                                </div>
                            </div>
                        </div>
                        <div className="d-flex flex-column align-items-center gap-2" style={{ minWidth: 40 }}>
                            <Button
                                variant="outline-secondary"
                                onClick={handleRefresh}
                                disabled={refreshing}
                                style={{ display: 'flex', alignItems: 'center', padding: 0, width: '38px', height: '38px', justifyContent: 'center' }}
                                title={polyglot.t('label.refresh')}
                            >
                                <FaSync
                                    style={{ fontSize: '1.25rem', color: darkMode ? '#8fa3c8' : '#222', width: '22px', height: '22px' }}
                                    className={refreshing ? 'fa-spin' : ''}
                                />
                            </Button>
                            <Button
                                variant="outline-secondary"
                                onClick={handleNotificationToggle}
                                style={{ display: 'flex', alignItems: 'center', padding: 0, width: '38px', height: '38px', justifyContent: 'center' }}
                            >
                                {notificationsEnabled ? (
                                    <FaBell style={{ fontSize: '1.25rem', color: darkMode ? '#8fa3c8' : '#222', width: '22px', height: '22px' }} />
                                ) : (
                                    <FaBellSlash style={{ fontSize: '1.25rem', color: darkMode ? '#8fa3c8' : '#222', width: '22px', height: '22px' }} />
                                )}
                            </Button>
                        </div>
                    </div>
                </Card.Header>
                <Card.Body style={darkMode ? { color: darkText, background: darkCard } : {}}>
                    <table className="table table-borderless mb-0" style={darkMode ? { background: darkCard, color: darkText, borderCollapse: 'separate', borderSpacing: 0 } : {}}>
                        <tbody>
                            <tr style={darkMode ? { background: '#151a23', color: darkText, borderBottom: '1.5px solid #232a3a' } : {}}>
                                <th scope="row" style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '6px 0 0 6px', padding: '2px 8px', fontWeight: 500, borderRight: '1.5px solid #232a3a' } : {}}>{polyglot.t(`label.signal`)}</th>
                                <td style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '0 6px 6px 0', padding: '2px 8px 2px 0', textAlign: 'left', borderLeft: '1.5px solid #232a3a' } : { textAlign: 'left', padding: '2px 8px 2px 0' }}>
                                    <a href={href} target="_blank" rel="noopener noreferrer" className="badge px-4 py-2" style={{ display: 'inline-block', textAlign: 'left', paddingLeft: 0, textDecoration: 'none' }}>
                                        <div className="signal-pill-container" style={{ justifyContent: 'flex-start', display: 'flex', marginLeft: '-8px' }}>
                                            <SignalPill polyglot={polyglot} signal={signal} />
                                        </div>
                                    </a>
                                </td>
                            </tr>
                            {signal.signalReason !== "none" && (
                            <tr style={darkMode ? { background: '#151a23', color: darkText, borderBottom: '1.5px solid #232a3a' } : {}}>
                                <th scope="row" style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '6px 0 0 6px', padding: '2px 8px', fontWeight: 500, borderRight: '1.5px solid #232a3a' } : {}}>{polyglot.t(`label.signalReason`)}</th>
                                <td style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '0 6px 6px 0', padding: '2px 8px', borderLeft: '1.5px solid #232a3a' } : {}}>
                                    <span style={darkMode ? { background: 'transparent', color: darkText } : {}}>
                                        {polyglot.t(`signal.reason.${signal.signalReason}.${signal.signal}`)}&nbsp;
                                        {polyglot.t(`signal.reason.${signal.signalReason}.label`)}
                                    </span>
                                </td>
                            </tr>
                            )}
                            <tr style={darkMode ? { background: '#151a23', color: darkText, borderBottom: '1.5px solid #232a3a' } : {}}>
                                <th scope="row" style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '6px 0 0 6px', padding: '2px 8px', fontWeight: 500, borderRight: '1.5px solid #232a3a' } : {}}>{polyglot.t("label.price")}</th>
                                <td style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '0 6px 6px 0', padding: '2px 8px', borderLeft: '1.5px solid #232a3a' } : {}}>
                                    {signal.price > 0 && (
                                        <span className="d-flex align-items-center" style={darkMode ? { background: 'transparent', color: darkText } : {}}>
                                            {signal.price}
                                            <Button variant="link" className="ms-2 p-0" onClick={() => copyToClipboard(signal.price)}>
                                                {copiedPrice === signal.price ? <FaCheck color="green" /> : <FaCopy />}
                                            </Button>
                                        </span>
                                    )}
                                </td>
                            </tr>

                            {signal.takeProfit > 0 && (
                            <>
                                <tr style={darkMode ? { background: '#151a23', color: darkText, borderBottom: '1.5px solid #232a3a' } : {}}>
                                <th scope="row" style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '6px 0 0 6px', padding: '2px 8px', fontWeight: 500, borderRight: '1.5px solid #232a3a' } : {}}>{polyglot.t("buySellModal.tp")}</th>
                                <td style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '0 6px 6px 0', padding: '2px 8px' } : {}}>
                                    <span className="d-flex align-items-center" style={darkMode ? { background: 'transparent', color: darkText } : {}}>
                                    {signal.takeProfit}
                                    <Button
                                        variant="link"
                                        className="ms-2 p-0"
                                        onClick={() => copyToClipboard(signal.takeProfit)}
                                    >
                                        {copiedPrice === signal.takeProfit ? (
                                        <FaCheck color="green" />
                                        ) : (
                                        <FaCopy />
                                        )}
                                    </Button>
                                    </span>
                                </td>
                                </tr>

                                <tr style={darkMode ? { background: '#151a23', color: darkText, borderBottom: '1.5px solid #232a3a' } : {}}>
                                <th scope="row" style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '6px 0 0 6px', padding: '2px 8px', fontWeight: 500, borderRight: '1.5px solid #232a3a' } : {}}>{polyglot.t("buySellModal.sl")}</th>
                                <td style={darkMode ? { background: '#1a2230', color: darkText, borderRadius: '0 6px 6px 0', padding: '2px 8px' } : {}}>
                                    {signal.stopLoss > 0 && (
                                    <span className="d-flex align-items-center" style={darkMode ? { background: 'transparent', color: darkText } : {}}>
                                        {signal.stopLoss}
                                        <Button
                                        variant="link"
                                        className="ms-2 p-0"
                                        onClick={() => copyToClipboard(signal.stopLoss)}
                                        >
                                        {copiedPrice === signal.stopLoss ? (
                                            <FaCheck color="green" />
                                        ) : (
                                            <FaCopy />
                                        )}
                                        </Button>
                                    </span>
                                    )}
                                </td>
                                </tr>
                            </>
                            )}

                        </tbody>
                    </table>
                    <div>
                        {isChartLoading ? (
                            <div style={{ textAlign: 'center', fontSize: '1.5rem', padding: '12px 0' }}>📊</div>
                        ) : (
                            <CandlestickChart ohlcData={ohlcData} polyglot={polyglot} />
                        )}
                    </div>
                </Card.Body>
                <Card.Footer style={darkMode ? { background: '#22304a', color: darkText } : {}}>
                    <Button variant="danger" onClick={() => setShowModal(true)}>
                        {polyglot.t("settingsPage.remove")}
                    </Button>
                </Card.Footer>
            </Card>

            {signal.market === "USD_M_FUTURES" && signal.takeProfit > 0 &&  (
            <Card className={`mt-3 text-center${darkMode ? ' crypto-details-card-dark' : ''}`}
                style={darkMode ? {
                    background: darkCard,
                    color: darkText,
                    border: `1px solid ${darkBorder}`,
                } : {}}>
                <Card.Header style={darkMode ? { background: '#22304a', color: darkText } : {}}>
                    {polyglot.t("cryptoDetails.leverage.title", "Select Leverage")}
                </Card.Header>
                <Card.Body style={darkMode ? { color: darkText } : {}}>
                    <div className="d-flex justify-content-center gap-2 flex-wrap mt-2">
                        {leverageOptions.map((leverage) => (
                            <Button
                                key={leverage}
                                variant={selectedLeverage === leverage ? "secondary" : "outline-secondary"}
                                onClick={() => setSelectedLeverage(leverage)}
                            >
                                {leverage}x
                            </Button>
                        ))}
                    </div>
                </Card.Body>
            </Card>
        )}
            {signal.price > 0 && signal.takeProfit > 0 && (
            <Card className={`mt-3 text-center${darkMode ? ' crypto-details-card-dark' : ''}`}
                style={darkMode ? {
                    background: darkCard,
                    color: darkText,
                    border: `1px solid ${darkBorder}`,
                } : {}}>
                <Card.Header style={darkMode ? { background: '#22304a', color: darkText } : {}}>
                    {polyglot.t("cryptoDetails.earnings.title")}
                </Card.Header>
                <Card.Body style={darkMode ? { color: darkText, background: darkCard } : {}}>
                    <table
                        className="table table-sm text-centered"
                        style={darkMode ? {
                            background: darkCard,
                            color: darkText,
                            borderCollapse: 'separate',
                            borderSpacing: 0,
                            border: 'none',
                            outline: 'none',
                            boxShadow: 'none',
                        } : { background: 'transparent', border: 'none', outline: 'none', boxShadow: 'none' }}
                    >
                        <thead style={darkMode ? {
                            background: '#22304a',
                            color: darkText,
                            borderBottom: '1.5px solid rgba(44,62,80,0.35)',
                        } : {}}>
                            <tr>
                                <th style={darkMode ? {
                                    background: '#22304a',
                                    color: darkText,
                                    borderRadius: '6px',
                                    padding: '2px 8px',
                                    fontWeight: 500,
                                    borderBottom: '1.5px solid rgba(44,62,80,0.25)',
                                } : {}}>{polyglot.t("cryptoDetails.earnings.investment")}</th>
                                <th style={darkMode ? {
                                    background: '#22304a',
                                    color: darkText,
                                    borderRadius: '6px',
                                    padding: '2px 8px',
                                    fontWeight: 500,
                                    borderBottom: '1.5px solid rgba(44,62,80,0.25)',
                                } : {}}>{polyglot.t("cryptoDetails.earnings.profit")}</th>
                            </tr>
                        </thead>
                        <tbody style={darkMode ? { background: darkCard, border: 'none', outline: 'none', boxShadow: 'none' } : { background: 'transparent', border: 'none', outline: 'none', boxShadow: 'none' }}>
                            {investmentAmounts.map((amount, idx) => {
                                // Determine if it's a BUY or SELL
                                const isBuy = signal.signal.toLowerCase() === "buy"; // You can adjust if your signal values are capitalized
                                const roi = isBuy
                                    ? (signal.takeProfit - signal.price) / signal.price
                                    : (signal.price - signal.takeProfit) / signal.price;

                                const profit = amount * roi * selectedLeverage;
                                const total = amount + profit;
                                const isLast = idx === investmentAmounts.length - 1;
                                return (
                                    <tr key={amount} style={darkMode ? {
                                        background: darkCard,
                                        color: darkText,
                                        borderBottom: isLast ? 'none' : '1.5px solid rgba(44,62,80,0.18)',
                                        border: 'none',
                                        outline: 'none',
                                        boxShadow: 'none',
                                    } : { background: 'transparent', border: 'none', outline: 'none', boxShadow: 'none' }}>
                                        <td style={darkMode ? {
                                            background: '#22304a',
                                            color: darkText,
                                            borderRadius: isLast ? '0 0 0 0' : '6px',
                                            padding: '2px 8px',
                                            border: 'none',
                                            outline: 'none',
                                            boxShadow: 'none',
                                        } : { border: 'none', outline: 'none', boxShadow: 'none' }}>${amount.toFixed(2)}</td>
                                        <td style={darkMode ? {
                                            background: '#22304a',
                                            color: darkText,
                                            borderRadius: isLast ? '0 0 0 0' : '6px',
                                            padding: '2px 8px',
                                            border: 'none',
                                            outline: 'none',
                                            boxShadow: 'none',
                                        } : { border: 'none', outline: 'none', boxShadow: 'none' }}>${profit.toFixed(2)}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </Card.Body>
            </Card>
        )}


            {showModal && (
                <ConfirmRemoveModal
                    show={showModal}
                    onHide={() => setShowModal(false)}
                    onConfirm={onConfirmRemove}
                    polyglot={polyglot}
                    signal={signal}
                    darkMode={darkMode}
                />
            )}

            {SessionExpiredModal}
        </Container>
    );
};

export default CryptoDetails;
