import Chart from 'react-apexcharts';
import { isDarkModeEnabled } from '../settings';

const CandlestickChart = ({ ohlcData, polyglot }) => {
  const darkMode = isDarkModeEnabled();
  const darkBg = '#101624'; // blueish, near-black
  const darkCard = '#18213a';
  const darkBorder = 'rgba(44, 62, 80, 0.6)';
  const darkText = '#e0e6f0';

  if (!ohlcData || ohlcData.length === 0) {
    return (
      <div>
      <span role="img" aria-label="chart" style={{ marginRight: 8 }}>📊</span>
      <em>{polyglot.t(`cryptoDetails.chart.nodata`)}</em>
      </div>
    );
  }

  // Format the data for ApexCharts
  const formatted = ohlcData.map(candle => ({
    x: new Date(candle[0]),
    y: [
      parseFloat(candle[1]), // open
      parseFloat(candle[2]), // high
      parseFloat(candle[3]), // low
      parseFloat(candle[4])  // close
    ]
  }));

  const series = [{ data: formatted }];

  const options = {
    chart: {
      type: 'candlestick',
      height: 350,
      toolbar: { show: false },
      zoom: { enabled: false },
      selection: { enabled: false },
      background: darkMode ? darkCard : '#fff',
      foreColor: darkMode ? darkText : '#222',
    },
    title: {
      text: '',
      align: 'left',
      style: { color: darkMode ? darkText : '#222' }
    },
    xaxis: {
      type: 'datetime',
      labels: {
        style: { colors: darkMode ? darkText : '#222' }
      },
      axisBorder: { color: darkMode ? darkBorder : '#e0e0e0' },
      axisTicks: { color: darkMode ? darkBorder : '#e0e0e0' },
    },
    yaxis: {
      tooltip: { enabled: false },
      labels: {
        style: { colors: darkMode ? darkText : '#222' }
      },
      axisBorder: { color: darkMode ? darkBorder : '#e0e0e0' },
      axisTicks: { color: darkMode ? darkBorder : '#e0e0e0' },
    },
    grid: {
      borderColor: darkMode ? darkBorder : '#e0e0e0',
    },
    tooltip: {
      theme: darkMode ? 'dark' : 'light',
      style: { fontSize: '14px', color: darkMode ? darkText : '#222' },
      x: { show: true },
      y: { show: true },
    },
    plotOptions: {
      candlestick: {
        colors: {
          upward: '#26a69a', // green for bullish
          downward: '#ef5350', // red for bearish
        },
        wick: {
          useFillColor: true,
        },
      },
    },
  };

  return (
    <Chart options={options} series={series} type="candlestick" height={350} />
  );
};

export default CandlestickChart;
