import React, { useEffect } from 'react';
import { Container, Card, Row, Col, Button } from 'react-bootstrap';
import { isDarkModeEnabled } from '../settings';
import { useNavigate } from 'react-router-dom';
import { getProfile as getProfileCache, getPlans } from '../sessionCache';
import BackButton from '../components/BackButton';
import { basepath } from './Header';

const PayWall = ({ polyglot }) => {
  const darkMode = isDarkModeEnabled();
  const navigate = useNavigate();
  const [user, setUser] = React.useState(null);
  const [plans, setPlans] = React.useState([]);
  const [loading, setLoading] = React.useState(true);

  // Scroll to top on mount
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, []);

  // Helper to translate feature keys
  const getFeatureText = (featureKey) =>
    polyglot && polyglot.t
      ? polyglot.t(`plan.features.${featureKey}`, featureKey)
      : featureKey;

  useEffect(() => {
    const loadData = async () => {
      try {
        const token = localStorage.getItem('jerryToken');
        const [profile, plansData] = await Promise.all([
          getProfileCache(token),
          getPlans(basepath)
        ]);
        setUser(profile);
        
        // Transform plans data to match the expected format
        const transformedPlans = Object.entries(plansData).map(([key, plan]) => ({
          key,
          emoji: key === 'elite' ? '🔥' : key === 'pro' ? '' : '',
          name: polyglot ? polyglot.t(`plan.${key}`, key.charAt(0).toUpperCase() + key.slice(1)) : key.charAt(0).toUpperCase() + key.slice(1),
          price: plan.price,
          features: [
            'timeframes',
            'maxTrackedCryptos',
            'refreshInternvalSec',
            'maxNotifications'
          ],
          planData: plan
        }));
        setPlans(transformedPlans);
      } catch (e) {
        setUser(null);
        setPlans([]);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, [polyglot]);

  if (loading) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100vh' }}>
        <div className="d-flex justify-content-center">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
        </div>
        <div className="mt-3">Loading plans...</div>
      </div>
    );
  }

  return (
    <Container
      className={darkMode ? 'profile-dark' : ''}
      style={darkMode ? {
        background: '#101624',
        color: '#e0e6f0',
        borderRadius: '12px',
        boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)',
        marginTop: '2rem',
        paddingBottom: '2rem',
      } : {
        background: '#fff',
        color: '#222',
        borderRadius: '12px',
        boxShadow: '0 2px 16px 0 rgba(16,22,36,0.08)',
        marginTop: '2rem',
        paddingBottom: '2rem',
      }}
    >
      <div className="mt-4">
        <BackButton polyglot={polyglot} />
      </div>
      <h2 className="text-center mt-4 mb-4" style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}>
        {polyglot ? polyglot.t('paywall.title', 'Upgrade Your Plan') : 'Upgrade Your Plan'}
      </h2>
      <Row className="justify-content-center">
        {plans.map(plan => {
          const isCurrent = user && user.plan_name && plan.key.toLowerCase() === user.plan_name.toLowerCase();
          return (
            <Col key={plan.key} xs={12} md={4} className="mb-4">
              <Card
                className="h-100 text-center"
                style={isCurrent
                  ? (darkMode
                      ? {
                          background: '#161b26',
                          color: '#8a97ad',
                          border: '2px solid #3a4252',
                          filter: 'grayscale(0.5)',
                          opacity: 0.7,
                        }
                      : {
                          background: '#f5f6fa',
                          color: '#a0a0a0',
                          border: '2px solid #e0e6f0',
                          filter: 'grayscale(0.5)',
                          opacity: 0.7,
                        })
                  : (darkMode
                      ? {
                          background: '#18213a',
                          color: '#e0e6f0',
                          border: '1px solid #22304a',
                          boxShadow: '0 2px 8px 0 rgba(16,22,36,0.12)',
                        }
                      : {
                          background: '#fff',
                          color: '#222',
                          border: '1px solid #e0e6f0',
                          boxShadow: '0 2px 8px 0 rgba(16,22,36,0.08)',
                        })
                }
              >
                <Card.Body>
                  {plan.emoji && <div style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>{plan.emoji}</div>}
                  <Card.Title style={{ fontWeight: 700, fontSize: '1.4rem' }}>{plan.name}</Card.Title>
                  <h3 style={{ fontWeight: 800, margin: '1rem 0' }}>{plan.price}</h3>
                  <ul style={{ listStyle: 'none', padding: 0, marginBottom: '1rem' }}>
                    {['1', '2', '3', '4', '5'].map(featureKey => (
                      <li key={featureKey} style={{ marginBottom: 6 }}>
                        {polyglot.t(`paywall.planDescriptions.${plan.key}.${featureKey}`)}
                      </li>
                    ))}
                  </ul>
                  {isCurrent && (
                    <div style={{ fontWeight: 600, color: darkMode ? '#7ca0b8' : '#a0a0a0', marginBottom: 8 }}>
                      {polyglot ? polyglot.t('paywall.currentPlan', 'Your current plan') : 'Your current plan'}
                    </div>
                  )}
                  {plan.key !== 'free' && !isCurrent && (
                    <Button
                      variant={plan.key === 'elite' ? 'warning' : 'primary'}
                      style={darkMode ? { color: '#18213a', fontWeight: 600 } : { fontWeight: 600 }}
                      onClick={() => navigate('/upgrade', { state: { plan: plan.key } })}
                    >
                      {polyglot ? polyglot.t('paywall.upgrade', 'Upgrade') : 'Upgrade'}
                    </Button>
                  )}
                </Card.Body>
              </Card>
            </Col>
          );
        })}
      </Row>
    </Container>
  );
};

export default PayWall;
