import React, { useEffect } from 'react';
import ReactDOM from 'react-dom';
import './index.css';
import App from "./App";
import { Auth0Provider, useAuth0 } from "@auth0/auth0-react";
import 'bootstrap/dist/css/bootstrap.min.css'; 
import registerServiceWorker from './registerServiceWorker';
import { Capacitor } from '@capacitor/core';
import { Browser } from '@capacitor/browser';
import { App as CapApp } from '@capacitor/app';

const isNative = Capacitor.isNativePlatform();

// Auth0 Config
const domain = process.env.REACT_APP_AUTH0_DOMAIN;
const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
const audience = process.env.REACT_APP_AUTH0_AUDIENCE;
const rawBasepath = process.env.PUBLIC_URL || '';
const basepath = rawBasepath === '.' ? '' : rawBasepath;
const redirectUri = isNative
  ? 'io.jerry.cryptobot://callback'
  : window.location.origin + basepath + '/jerry-app';

// ---- Wrapper to handle Capacitor redirect ----
function Auth0CapacitorProvider({ children }) {
  const { handleRedirectCallback } = useAuth0();

  useEffect(() => {
    if (!isNative) return;

    const listener = CapApp.addListener('appUrlOpen', async ({ url }) => {
      if (url.startsWith('io.jerry.cryptobot://callback')) {
        try {
          await handleRedirectCallback(url);
          await Browser.close();
          // Clean up the URL so user doesn't stay on blank page
          window.history.replaceState({}, document.title, '/');
        } catch (err) {
          console.error("Auth0 redirect handling failed", err);
        }
      }
    });

    return () => {
      listener.remove();
    };
  }, [handleRedirectCallback]);

  return <>{children}</>;
}

// ---- Render Root ----
ReactDOM.render(
  <Auth0Provider
    domain={domain}
    clientId={clientId}
    authorizationParams={{
      redirect_uri: redirectUri,
      audience: audience,
    }}
    cacheLocation="localstorage"
  >
    <Auth0CapacitorProvider>
      <App />
    </Auth0CapacitorProvider>
  </Auth0Provider>,
  document.getElementById("root")
);

registerServiceWorker();
