import React, { useState, useEffect } from 'react';
import SignalFilters from '../components/SignalFilters';
import { Container } from 'react-bootstrap';
import { toast } from 'react-toastify';
import SignalData from '../components/SignalData';
import useSessionExpired from '../hooks/useSessionExpired';
import { useLocation } from 'react-router-dom';
import './MainPage.css'; // Import the CSS file
import { isDarkModeEnabled } from '../settings'; // Import the dark mode utility
import { isShowFiltersEnabled, saveShowFilters, getFilterValue, saveFilterValue } from '../settings';

const MainPage = ({ polyglot, setRefreshKey }) => {
    // Collapsible filter state
    const [showFilters, setShowFilters] = useState(isShowFiltersEnabled());
    // --- FILTER STATE ---
    const [filters, setFilters] = useState({ market: null, signal: null, reason: null });
    // Filter count state
    const [filterCount, setFilterCount] = useState(0);
    // Load individual filters from localStorage on mount
    useEffect(() => {
        const initialFilters = {
            market: getFilterValue('market'),
            signal: getFilterValue('signal'),
            reason: getFilterValue('reason'),
        };
        setFilters(initialFilters);
        // Set initial filter count based on loaded filters
        const initialCount = [initialFilters.market, initialFilters.signal, initialFilters.reason].filter(Boolean).length;
        setFilterCount(initialCount);
    }, []);
    // Persist each filter to localStorage when changed
    useEffect(() => {
        saveFilterValue('market', filters.market);
        saveFilterValue('signal', filters.signal);
        saveFilterValue('reason', filters.reason);
    }, [filters]);
    const [lastUpdated, setLastUpdated] = useState(null);
    const [refreshSignal, setRefreshSignal] = useState(0); // Use a counter to guarantee uniqueness
    const [loading, setLoading] = useState(true); // Default to true for initial load
    // const [alertMessage, setAlertMessage] = useState(null); // Track alert message
    const location = useLocation();
    const darkMode = isDarkModeEnabled(); // Check if dark mode is enabled

    // Scroll to top on mount
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'auto' });
    }, []);

    useEffect(() => {
        if (location.state?.alert) {
            toast.warn(location.state.alert, {
                theme: darkMode ? 'dark' : 'light',
            });
            window.history.replaceState({}, document.title); // Clear the state from the history
            triggerRefresh();
        }
    }, [location.state, darkMode]);

    const handleDataLoaded = (timestamp) => {
        setLastUpdated(timestamp);
        setLoading(false); // Stop showing "Loading..." once data is loaded
    };

    const triggerRefresh = () => {
        setLoading(true); // Show "Loading..." immediately
        setRefreshSignal((prev) => prev + 1); // Increment refreshSignal to trigger refresh
    };

    const SessionExpiredModal = useSessionExpired(polyglot);

    // Automatically refresh every minute
    useEffect(() => {
        const interval = setInterval(() => {
            triggerRefresh();
        }, 60000);

        return () => clearInterval(interval);
    }, []); // Run only once on mount

    return (
        <Container
            className={`main-container${darkMode ? ' dark-mode' : ''}`}
            style={darkMode ? {
                background: '#101624', // blueish, near-black
                color: '#e0e6f0',
                minHeight: '100vh',
                borderRadius: '12px',
                boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)'
            } : {}}
        >
            {/* Alert replaced by react-toastify toast */}

           

            <div
                className="refresh-container"
                style={darkMode ? {
                    background: '#18213a',
                    color: '#e0e6f0',
                    borderRadius: '8px',
                    padding: '0.5rem 1rem',
                    marginBottom: '1rem',
                    boxShadow: '0 1px 4px 0 rgba(16,22,36,0.2)'
                } : {}}
            >
                {loading ? (
                    <span>{polyglot.t('label.loading')}</span>
                ) : (
                    <span>
                        {lastUpdated || ''}
                    </span>
                )}
            </div>


            <div style={{ marginBottom: 12 }}>
                <button
                    onClick={() => {
                        setShowFilters((prev) => {
                            const next = !prev;
                            saveShowFilters(next);
                            return next;
                        });
                    }}
                    style={{
                        background: darkMode ? '#18213a' : '#f0f4fa',
                        color: darkMode ? '#e0e6f0' : '#222',
                        border: 'none',
                        borderRadius: 8,
                        padding: '8px 18px',
                        fontWeight: 400,
                        fontSize: '1rem', // Match last updated date font size
                        cursor: 'pointer',
                        width: '100%',
                        marginBottom: showFilters ? 8 : 0,
                        boxShadow: darkMode ? '0 1px 4px 0 rgba(16,22,36,0.2)' : '0 1px 4px 0 rgba(180,180,180,0.08)'
                    }}
                    aria-expanded={showFilters}
                    aria-controls="signal-filters-container"
                >
                    {showFilters
                        ? polyglot.t('filters.hide')
                        : polyglot.t('filters.show') + (filterCount > 0 ? ` (${filterCount})` : '')}
                </button>
                {showFilters && (
                    <div id="signal-filters-container">
                        <SignalFilters
                            filters={filters}
                            onChange={setFilters}
                            polyglot={polyglot}
                            darkMode={darkMode}
                            availableMarkets={['USD_M_FUTURES', 'SPOT']}
                            availableSignals={['buy', 'sell']}
                            availableReasons={['spike', 'reversal', 'trend']}
                            onCountChange={setFilterCount}
                        />
                    </div>
                )}
            </div>

            <SignalData
                refreshSignal={refreshSignal}
                onDataLoaded={handleDataLoaded}
                triggerRefresh={triggerRefresh}
                polyglot={polyglot}
                filters={filters}
            />

            {SessionExpiredModal}
        </Container>
    );
};

export default MainPage;
