import React, { useEffect, useState } from "react";
import { Card, Row, Col, Spinner, Container } from "react-bootstrap";
import { getAllNotificationsConfigs, deleteNotificationConfig } from "../api";
import ConfirmNotificationRemovalModal from "../components/ConfirmNotificationRemovalModal";
import { getUserData } from "../jerryTokenUtil";
import { isDarkModeEnabled, saveDarkMode } from "../settings";
import { Switch, FormControlLabel } from '@mui/material';
import { FaBell, FaTrashAlt } from "react-icons/fa";
import BackButton from "../components/BackButton";

const Settings = ({ polyglot }) => {
  // ...existing code...
  useEffect(() => {
    const fetchConfigs = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem("jerryToken");
        const result = await getAllNotificationsConfigs(token);
        setConfigs(result || []);
      } catch (err) {
        setError(err.message || "Error loading notifications");
      } finally {
        setLoading(false);
      }
    };
    fetchConfigs();
  }, []);
  const [configs, setConfigs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  // Modal state for confirmation
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [pendingRemoveConfig, setPendingRemoveConfig] = useState(null);

  const handleRemoveClick = (id) => {
    const cfg = configs.find((cfg, idx) => (cfg.crypto_pair + cfg.market_name + cfg.timeframe + idx) === id);
    if (!cfg) return;
    setPendingRemoveConfig(cfg);
    setShowConfirmModal(true);
  };

  const handleConfirmRemove = async () => {
    if (!pendingRemoveConfig) return;
    setShowConfirmModal(false);
    setLoading(true);
    setError(null);
    const token = localStorage.getItem("jerryToken");
    try {
      await deleteNotificationConfig(token, pendingRemoveConfig.crypto_pair, pendingRemoveConfig.market_name, pendingRemoveConfig.timeframe);
      // Refresh configs after deletion
      const result = await getAllNotificationsConfigs(token);
      setConfigs(result || []);
    } catch (err) {
      setError(err.message || "Error removing notification");
    } finally {
      setLoading(false);
      setPendingRemoveConfig(null);
    }
  };
  const [darkMode, setDarkMode] = useState(isDarkModeEnabled());

  // Dark mode toggle logic
  const handleDarkModeToggle = () => {
    setDarkMode((prev) => !prev);
    saveDarkMode(!darkMode);
  };
  return (
    <Container
      className={`mt-4 notifications-container${darkMode ? ' profile-dark' : ''}`}
      style={darkMode ? {
        background: '#101624',
        color: '#e0e6f0',
        borderRadius: '12px',
        boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)',
        minHeight: '60vh',
        paddingBottom: '2rem'
      } : { color: '#222', minHeight: '60vh', paddingBottom: '2rem' }}
    >
  <BackButton polyglot={polyglot} />
  {/* Reduce margin to match Profile page */}
  <div style={{ height: '0.2rem' }} />
      {/* Settings Section: Dark Mode Toggle */}
      <Card
        className={`text-center mt-4${darkMode ? ' profile-card-dark' : ''}`}
        style={darkMode ? {
          background: '#18213a',
          color: '#e0e6f0',
          border: '1px solid #22304a',
        } : { color: '#222' }}
      >
        <Card.Header style={darkMode ? { background: '#22304a', color: '#e0e6f0' } : { color: '#222' }}>
          <h5 style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}>{polyglot.t("settingsPage.appearanceTitle")}</h5>
        </Card.Header>
        <Card.Body className="text-left" style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}>
          <FormControlLabel
            control={<Switch checked={darkMode} onChange={handleDarkModeToggle} />}
            label={<span style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}>{polyglot.t('profile.settings.darkMode')}</span>}
            style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}
          />
        </Card.Body>
      </Card>
      {loading ? (
        <div style={{ textAlign: "center", marginTop: "2rem" }}>
          <Spinner animation="border" variant={darkMode ? "light" : "primary"} />
          <div style={{ marginTop: 12 }}>{polyglot.t("notifications.loading")}</div>
        </div>
      ) : error ? (
        <div style={{ color: "#e57373", textAlign: "center" }}>{polyglot.t("notifications.error")}</div>
      ) : configs.length === 0 ? (
        <div style={{ textAlign: "center", color: darkMode ? "#e0e6f0" : "#222" }}>
          {polyglot.t("notifications.empty")}
        </div>
      ) : (
        <Card
          className={`text-center mt-4${darkMode ? ' profile-card-dark' : ''}`}
          style={darkMode ? {
            background: '#141b2d', // darker than before
            color: '#e0e6f0',
            border: '1px solid #22304a',
          } : { color: '#222' }}
        >
          <Card.Header style={darkMode ? { background: '#22304a', color: '#e0e6f0' } : { color: '#222' }}>
            <h5 style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}>{polyglot.t("settings.notificationsEnabledTitle")}</h5>
          </Card.Header>
          <Card.Body style={darkMode ? { color: '#e0e6f0' } : { color: '#222' }}>
            <Row xs={1} sm={2} md={3} lg={4} className="g-4">
              {configs.map((cfg, idx) => {
                const symbol = cfg.crypto_pair;
                const market = cfg.market_name;
                const timeframe = cfg.timeframe;
                const types = [
                  cfg.notify_trend ? { key: 'trend', icon: '📊' } : null,
                  cfg.notify_reversal ? { key: 'reversal', icon: '🔄' } : null,
                  cfg.notify_spike ? { key: 'spike', icon: '⚡' } : null
                ].filter(Boolean);
                return (
                  <Col key={symbol + market + timeframe + idx}>
                    <Card className={`shadow-sm mb-2${darkMode ? " signal-card-dark" : ""}`} style={{ borderRadius: 12, background: darkMode ? "#18213a" : "#fff", color: darkMode ? "#e0e6f0" : "#222", position: "relative" }}>
                      <Card.Body style={{ textAlign: 'left' }}>
                        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                          </div>
                              <FaBell size={20} style={{ marginRight: 6, color: darkMode ? "#4fd1c5" : "#FF9800" }} />
                              <span style={{ fontWeight: 600, fontSize: "1.1em" }}>
                                {polyglot.t(`cryptoPairs.${symbol}`)}
                              </span>
                              <span className="badge" style={{ background: darkMode ? "#22304a" : "#eee", color: darkMode ? "#e0e6f0" : "#222", marginLeft: 8, fontSize: "0.9em" }}>
                                {timeframe}
                              </span>
                              <FaTrashAlt size={18} style={{ cursor: "pointer", color: "#e57373", marginLeft: 'auto' }} title={polyglot.t("notifications.remove" )} onClick={() => handleRemoveClick(symbol + market + timeframe + idx)} />
                        </div>
                        <div style={{ marginTop: 10, fontSize: "0.98em", textAlign: 'left' }}>
                          <div style={{ textAlign: 'left' }}>
                            {polyglot.t(`markets.${market}`)}
                          </div>
                          <div style={{ marginTop: 6, textAlign: 'left' }}>
                            {types.length === 0 ? (
                              <span style={{ color: "#aaa" }}>{polyglot.t("notifications.none")}</span>
                            ) : (
                              types.map(t => (
                                <span key={t.key} style={{ marginRight: 8, fontSize: "1.2em", textAlign: 'left' }}>
                                  {t.icon}
                                  <span style={{ fontSize: '0.75em', marginLeft: 2 }}>{polyglot.t(`signal.reason.${t.key}.label`)}</span>
                                </span>
                              ))
                            )}
                          </div>
                        </div>
                      </Card.Body>
                    </Card>
                  </Col>
                );
              })}
            </Row>
          </Card.Body>
        </Card>
      )}
      {/* Confirmation Modal for Notification Removal */}
      <ConfirmNotificationRemovalModal
        show={showConfirmModal}
        onHide={() => setShowConfirmModal(false)}
        onConfirm={handleConfirmRemove}
        config={pendingRemoveConfig || {}}
        polyglot={polyglot}
        darkMode={darkMode}
      />
    </Container>
  );
}
export default Settings;
