import { Modal, Button } from 'react-bootstrap';

const ConfirmNotificationRemovalModal = ({ show, onHide, onConfirm, config, polyglot, darkMode }) => {
  const marketName = polyglot.t(`markets.${config.market_name}`);
  return (
    <Modal show={show} onHide={onHide} centered>
      <div style={darkMode ? { background: '#101624', borderRadius: 8 } : {}}>
        <Modal.Header closeButton style={darkMode ? { background: '#101624', color: '#e0e6f0', borderBottom: '1px solid rgba(44, 62, 80, 0.6)' } : {}}>
          <Modal.Title style={darkMode ? { color: '#e0e6f0' } : {}}>{polyglot.t('settingsPage.notificationsConfirmRemoveTitle')}</Modal.Title>
        </Modal.Header>
        <Modal.Body style={darkMode ? { background: '#18213a', color: '#e0e6f0' } : {}}>
          {polyglot.t('settingsPage.notificationsConfirmRemoveText', {
            crypto: polyglot.t(`cryptoPairs.${config.crypto_pair}`),
            timeframe: polyglot.t(`timeframesShort.${config.timeframe}`) || config.timeframe,
            market: marketName
          })}
        </Modal.Body>
        <Modal.Footer style={darkMode ? { background: '#101624', borderTop: '1px solid rgba(44, 62, 80, 0.6)' } : {}}>
          <Button variant={darkMode ? undefined : 'secondary'} style={darkMode ? { background: '#22304a', color: '#e0e6f0', border: 'none' } : {}} onClick={onHide}>
            {polyglot.t('label.cancel')}
          </Button>
          <Button variant={darkMode ? undefined : 'danger'} style={darkMode ? { background: '#e57373', color: '#e0e6f0', border: 'none' } : {}} onClick={onConfirm}>
            {polyglot.t('label.confirm')}
          </Button>
        </Modal.Footer>
      </div>
    </Modal>
  );
};

export default ConfirmNotificationRemovalModal;
