import { getUserData } from "./jerryTokenUtil";

// Notification queue persistence
export const getNotificationsKey = () => {
    const userData = getUserData();
    if (!userData) {
        return 'notifications';
    }
    return userData.hashedEmail + '.notifications';
};

export const saveNotificationsQueue = (notification) => {
    // Get current notifications array
    const key = getNotificationsKey();
    let arr = [];
    try {
        const val = localStorage.getItem(key);
        if (val) {
            arr = JSON.parse(val);
            if (!Array.isArray(arr)) arr = [];
        }
    } catch {
        arr = [];
    }
    // Add new notification
    arr.push(notification);
    localStorage.setItem(key, JSON.stringify(arr));
};

export const getNotificationsQueue = () => {
    const val = localStorage.getItem(getNotificationsKey());
    if (!val) return [];
    try {
        const arr = JSON.parse(val);
        return Array.isArray(arr) ? arr : [];
    } catch {
        return [];
    }
};

export const clearNotificationsQueue = () => {
    localStorage.removeItem(getNotificationsKey());
};
