// Individual filter persistence
export const getFilterKey = (filterName) => {
    const userData = getUserData();
    if (!userData) {
        return `filter.${filterName}`;
    }
    return `${userData.hashedEmail}.filter.${filterName}`;
};

export const saveFilterValue = (filterName, value) => {
    localStorage.setItem(getFilterKey(filterName), value ?? '');
};

export const getFilterValue = (filterName) => {
    const val = localStorage.getItem(getFilterKey(filterName));
    return val === '' ? null : val;
};

// Show/hide filter UI state persistence
export const getShowFiltersKey = () => {
    const userData = getUserData();
    if (!userData) {
        return 'showFilters';
    }
    return userData.hashedEmail + '.showFilters';
};

export const saveShowFilters = (show) => {
    localStorage.setItem(getShowFiltersKey(), show ? 'true' : 'false');
};

export const isShowFiltersEnabled = () => {
    const val = localStorage.getItem(getShowFiltersKey());
    // Default to true if not set
    return val === null ? true : val === 'true';
};

const getDarkModeKey = () => {
    const userData = getUserData();
    if (!userData){ 
        return "false";
    }
    return userData.hashedEmail + ".darkMode";
}

export const saveDarkMode = (isDarkMode) => {
    localStorage.setItem(getDarkModeKey(), isDarkMode);
}

export const isDarkModeEnabled = () => {
    const darkModeValue = localStorage.getItem(getDarkModeKey());
    return darkModeValue === 'true';
}